"""1500 (#11 power_upgrade_variants): Record-Coverage-v1494.ps1 with Corvo's entity-changing upgrades. The new step
'snap L' copies both roles' power status files (Windblast effects, swarm world, rat visuals, swarm spawn effects, power
effects, clone world and visual) under label L. Cases:
- 'upgshockwave2': Windblast with Shockwave cast in the 6 m fall (as 1456a), snapped after the landing: 1214ei lists the
  windblast-named effects the source saw while variant 11 ran (1456a: no shockwave effect reached the partner);
- 'upgwbgreater': Windblast with Greater Windblast cast standing (wblast_stronger_blast_01 is not the replicated record);
- 'upgswarmdouble': Devouring Swarm with Double Swarm, cast twice (the swarm reader follows one committed swarm);
- 'upgswarmbigger': Devouring Swarm with Bigger Swarm (the reader allows 100 agents);
- 'upgswarmfollow': Devouring Swarm with Follow Player, cast, then Corvo walks forward 2.5 s.
Generated by make_coverage_v1500.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1494.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
first = s.index('\n') + 1
s = s[:first] + "# 1500 (#11): Corvo's entity-changing upgrades (Shockwave and Greater Windblast effects, Double/Bigger/Follow Swarm). Generated by make_coverage_v1500.py.\n" + s[first:]
CASES = ['upgshockwave2', 'upgwbgreater', 'upgswarmdouble', 'upgswarmbigger', 'upgswarmfollow']
rep("'upgpossess2','upgtwinshade2'", "'upgpossess2','upgtwinshade2'," + ','.join(f"'{c}'" for c in CASES), 3)
rep("upgtwinshade2=16000", "upgtwinshade2=16000;upgshockwave2=11000;upgwbgreater=9000;upgswarmdouble=14000;upgswarmbigger=9000;upgswarmfollow=11000")
A = 'components/characters/player/base/attributes/'
W = 'models/powers/windblast/windblast.inventoryitem'
SW = 'models/powers/devouring_swarm/devouring_swarm.inventoryitem'
rep("     nomana2=@(",
    f"     upgshockwave2=@(@(600,'hold','on'),@(800,'named','{W}'),@(1700,'named','{A}windblast_shockwave.inventoryitem'),@(2400,'watchmid',8000),@(2800,'selfcmd','setviewpos -35 -153 74.10 0 0'),@(3300,'lt',250),@(5200,'snap','land'),@(8500,'snap','late'),@(10500,'hold','off'));\n"
    f"     upgwbgreater=@(@(600,'hold','on'),@(800,'named','{W}'),@(1700,'named','{A}windblast_greater.inventoryitem'),@(2400,'watchmid',6000),@(3000,'lt',250),@(4500,'snap','cast'),@(7000,'snap','late'),@(8500,'hold','off'));\n"
    f"     upgswarmdouble=@(@(600,'hold','on'),@(800,'named','{SW}'),@(1700,'named','{A}devouring_swarm_double.inventoryitem'),@(2400,'watchmid',11000),@(2800,'pitch',15),@(3200,'lt',250),@(5800,'snap','one'),@(6500,'lt',250),@(9500,'snap','two'),@(12500,'snap','late'),@(13500,'hold','off'));\n"
    f"     upgswarmbigger=@(@(600,'hold','on'),@(800,'named','{SW}'),@(1700,'named','{A}devouring_swarm_bigger.inventoryitem'),@(2400,'watchmid',6000),@(2800,'pitch',15),@(3200,'lt',250),@(5500,'snap','cast'),@(7500,'snap','late'),@(8500,'hold','off'));\n"
    f"     upgswarmfollow=@(@(600,'hold','on'),@(800,'named','{SW}'),@(1700,'named','{A}devouring_swarm_follow_player.inventoryitem'),@(2400,'watchmid',8000),@(2800,'pitch',15),@(3200,'lt',250),@(4600,'fwdasync',2500),@(6000,'snap','walk'),@(8800,'snap','late'),@(10500,'hold','off'));\n"
    "     nomana2=@(")
rep("'snapdg'{",
    "'snap'{foreach($q in @($source,$peer)){foreach($suffix in '.windblast-fx.json','.swarm-world.json','.swarm-rat-visual.json','.swarm-spawn-fx.json','.swarm-trails.json','.power-fx.json','.power-fx-stream.json','.doppelganger-world.json','.doppelganger-visual.json'){try{Copy-Item -LiteralPath \"$root/work/lab-instances/$q/coop-status.json$suffix\" -Destination \"$out/$key-$($d[2])-$q$suffix\" -ErrorAction Stop}catch{}}}};'snapdg'{")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-Coverage-v1500.ps1').write_bytes(out.encode('utf-8'))
print('ok')
